def rwh(share, sc, at, m):
    for r in N["rootweak_harm"][str(share)]:
        if r["scenario"] == sc and r["attack"] == at: return r.get(m)
RWH = lambda sh, sc, at, m: v(rwh(sh, sc, at, m))
def AGV(k, m): return AG[k]["harm"].get(m)
def f1(x, nd=1): return "—" if x is None else f"{x:+.{nd}f}"
